// ================= SPLASH بخط اخضر =================
class QuranApp extends StatefulWidget { const QuranApp({super.key}); @override State<QuranApp> createState() => _QuranAppState(); }
class _QuranAppState extends State<QuranApp> {
  double fs=22; bool dark=true; String reciter="ياسر الدوسري"; bool loaded=false; double prog=0;
  @override void initState(){ super.initState(); _startLoad(); }
  _startLoad() async {
    for(int i=0;i<=100;i++){ await Future.delayed(const Duration(milliseconds: 20)); setState(()=>prog=i/100); }
    final p=await SharedPreferences.getInstance(); setState((){ fs=p.getDouble('fs')??22; dark=p.getBool('dark')??true; reciter=p.getString('reciter')??"ياسر الدوسري"; loaded=true; });
  }
  @override Widget build(BuildContext context){
    return MaterialApp(debugShowCheckedModeBanner:false, theme: dark? ThemeData.dark(useMaterial3:true).copyWith(scaffoldBackgroundColor:const Color(0xFF0A0A0A)):ThemeData.light(useMaterial3:true),
      home:!loaded? Splash(prog:prog): Home(fs:fs,dark:dark,reciter:reciter,onChanged:(f,d,r) async { final p=await SharedPreferences.getInstance(); await p.setDouble('fs',f); await p.setBool('dark',d); await p.setString('reciter',r); setState((){fs=f; dark=d; reciter=r;}); }));
  }
}

class Splash extends StatelessWidget { final double prog; const Splash({super.key,required this.prog});
  @override Widget build(BuildContext context){
    return Scaffold(backgroundColor:const Color(0xFF0A0A0A), body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[
      const Icon(Icons.menu_book_rounded,size:80,color:Color(0xFF00FF88)),
      const SizedBox(height:20), const Text("نور القلوب",style:TextStyle(color:Colors.white,fontSize:32,fontWeight:FontWeight.bold)),
      const Text("صدقة جارية لروح المرحوم ناصر عزيز",style:TextStyle(color:Colors.white38,fontSize:12)),
      const SizedBox(height:40),
      Padding(padding:const EdgeInsets.symmetric(horizontal:40), child:Column(children:[LinearProgressIndicator(value:prog,color:const Color(0xFF00FF88),backgroundColor:Colors.white10,minHeight:6,borderRadius:BorderRadius.circular(10)), const SizedBox(height:10), Text("يتم تحميل الآيات... ${(prog*100).toInt()}%",style:const TextStyle(color:Color(0xFF00FF88),fontSize:11))]))
    ])));
  }
}

