class QuizRoom extends StatefulWidget { const QuizRoom({super.key}); @override State<QuizRoom> createState()=> _QuizRoomState(); }
class _QuizRoomState extends State<QuizRoom> {
  int q=0, score=0; bool answered=false; int? sel;
  final List<Map<String,dynamic>> qs=[
    {"q":"كم عدد سور القرآن الكريم؟","o":["110","114","120"],"a":1},
    {"q":"ما هي أطول سورة؟","o":["البقرة","آل عمران","النساء"],"a":0},
    {"q":"سورة الفاتحة كم آية؟","o":["6","7","8"],"a":1},
    {"q":"من هو خاتم الأنبياء؟","o":["موسى","عيسى","محمد ﷺ"],"a":2},
  ];
  @override Widget build(BuildContext context){
    return Scaffold(appBar:AppBar(title:const Text("غرفة الأسئلة - 3 أشخاص"),centerTitle:true,backgroundColor:const Color(0xFF111111)), body:Padding(padding:const EdgeInsets.all(16), child:Column(children:[
      Row(mainAxisAlignment:MainAxisAlignment.spaceEvenly,children: List.generate(3, (i)=>Column(children:[CircleAvatar(radius:25,backgroundColor:i==0?const Color(0xFF00FF88):Colors.white10,child:Text("ش${i+1}",style:TextStyle(color:i==0?Colors.black:Colors.white))), const SizedBox(height:4), Text(i==0?"أنت":"صديق ${i+1}",style:const TextStyle(fontSize:10))]))),
      const SizedBox(height:20),
      Card(color:const Color(0xFF1C1C1C), child:Padding(padding:const EdgeInsets.all(16), child:Column(children:[Text("سؤال ${q+1} / ${qs.length}",style:const TextStyle(color:Color(0xFF00FF88),fontSize:12)), const SizedBox(height:10), Text(qs[q]["q"],style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold),textAlign:TextAlign.center), const SizedBox(height:20),...List.generate(3, (i){ bool isCorrect=i==qs[q]["a"]; bool isSelected=sel==i; Color col=Colors.white10; if(answered){ if(isCorrect) col=const Color(0xFF00FF88).withOpacity(0.4); else if(isSelected) col=Colors.red.withOpacity(0.4); } else if(isSelected) col=Colors.white24; return Container(margin:const EdgeInsets.only(bottom:8), child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:col,minimumSize:const Size(double.infinity,50)), onPressed: answered? null:(){ setState(()=>sel=i); }, child:Text(qs[q]["o"][i],style:const TextStyle(color:Colors.white)))); }), const SizedBox(height:10), if(!answered) ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:const Color(0xFF00FF88)), onPressed: sel==null? null:(){ setState(()=>answered=true); if(sel==qs[q]["a"]) score++; }, child:const Text("تأكيد الإجابة",style:TextStyle(color:Colors.black))) else ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Colors.white), onPressed:(){ if(q < qs.length-1){ setState(()=>{q++, answered=false, sel=null}); } else { showDialog(context:context,builder:(_)=>AlertDialog(backgroundColor:const Color(0xFF1C1C1C),title:Text("النتيجة: $score / ${qs.length}",style:const TextStyle(color:Color(0xFF00FF88))),content:const Text("أحسنت! ثواب هذه المسابقة لروح المرحوم ناصر عزيز"),actions:[TextButton(onPressed:(){ Navigator.pop(context); setState(()=>{q=0,score=0,answered=false,sel=null}); },child:const Text("إعادة"))])); } }, child:Text(q < qs.length-1? "السؤال التالي":"عرض النتيجة",style:const TextStyle(color:Colors.black))) ]))),
      const SizedBox(height:20), Text("النقاط: $score",style:const TextStyle(color:Color(0xFF00FF88),fontSize:16))
    ])));
  }
}

